<?php
$title='Leads';$subtitle='Your CRM – won scraped businesses and enquiries from forms, ads & webhooks';
if(is_post()){
  $a=$_POST['a']??'';
  try{
  if($a==='add'){
    $d=array_intersect_key(array_map('trim',$_POST),array_flip(CRM::CORE));
    if(($d['name']??'')===''&&($d['contact_name']??'')==='')throw new Exception('Enter a name or business name.');
    $id=CRM::create($d,'manual',user()['name']??'',[]);
    CRM::saveCustom($id,$_POST['cf']??[]);
    if(!empty($_POST['status'])&&$_POST['status']!=='new')CRM::setStatus($id,$_POST['status']);
    flash('Lead added.');redirect(url('lead',['id'=>$id]));}
  if($a==='import'){
    if(empty($_FILES['csv']['tmp_name'])||!is_uploaded_file($_FILES['csv']['tmp_name']))throw new Exception('Choose a CSV file.');
    flash(CRM::import($_FILES['csv']['tmp_name']).' lead(s) imported.');redirect(url('leads',['src'=>'import']));}
  $ids=array_map('intval',$_POST['ids']??[]);
  if(strpos($a,'auto:')===0){$au=DB::row('SELECT * FROM automations WHERE id=?',[(int)substr($a,5)]);$n=0;if($au)foreach($ids as $i)if(Automation::start($au,$i,true))$n++;flash($n.' lead(s) added to automation "'.e($au['name']??'').'".');}
  elseif($a==='initiate'){flash(Outreach::initiate($ids,['auto'=>0]).' lead(s) queued for audit & report.');}
  else flash(e(Outreach::bulk($a,$ids)));}
  catch(Throwable $e){flash(e($e->getMessage()),'err');}
  back(url('leads'));}
$view=($_GET['view']??($_COOKIE['lv']??'list'))==='board'?'board':'list';
setcookie('lv',$view,time()+86400*365,'/');
$q=trim($_GET['q']??'');$st=$_GET['status']??'';$src=$_GET['src']??'';$tag=trim($_GET['tag']??'');$own=$_GET['own']??'';$fu=$_GET['fu']??'';
$w=['l.is_lead=1'];$a=[];
if($q!==''){$w[]='(l.name LIKE ? OR l.contact_name LIKE ? OR l.email LIKE ? OR l.phone LIKE ? OR l.city LIKE ? OR l.tags LIKE ? OR l.custom LIKE ?)';array_push($a,...array_fill(0,7,'%'.$q.'%'));}
if(isset(crm_statuses()[$st])&&$view==='list'){$w[]='l.status=?';$a[]=$st;}
if(isset(lead_sources()[$src])){$w[]='l.source=?';$a[]=$src;}
if($tag!==''){$w[]='l.tags LIKE ?';$a[]='%'.$tag.'%';}
if($own==='me'){$w[]='l.assigned_to=?';$a[]=user()['id'];}elseif($own==='none')$w[]='l.assigned_to IS NULL';
if($fu==='due')$w[]='l.follow_up_at IS NOT NULL AND l.follow_up_at<=NOW()';
$where=implode(' AND ',$w);
if(isset($_GET['export']))Outreach::csv(DB::all("SELECT l.* FROM leads l WHERE $where ORDER BY l.id DESC",$a));
$total=(int)DB::val("SELECT COUNT(*) FROM leads l WHERE $where",$a);
$per=$view==='board'?500:50;$pg=max(1,(int)($_GET['p']??1));$pages=max(1,(int)ceil($total/$per));
$leads=DB::all("SELECT l.*,u.name owner FROM leads l LEFT JOIN users u ON u.id=l.assigned_to WHERE $where ORDER BY COALESCE(l.lead_at,l.created_at) DESC,l.id DESC LIMIT $per OFFSET ".(($pg-1)*$per),$a);
$sc=[];foreach(DB::all('SELECT source,COUNT(*) n FROM leads WHERE is_lead=1 GROUP BY source') as $r)$sc[$r['source']]=(int)$r['n'];
$k=DB::row("SELECT COUNT(*) t,SUM(status='new') nw,SUM(created_at>=CURDATE()) td,SUM(status='won') wn,SUM(CASE WHEN status='won' THEN deal_value ELSE 0 END) wv,SUM(follow_up_at IS NOT NULL AND follow_up_at<=NOW() AND status NOT IN ('won','lost')) due FROM leads WHERE is_lead=1");
$users=DB::all('SELECT id,name FROM users ORDER BY name');
$autos=DB::all('SELECT id,name FROM automations ORDER BY name');
$qs=fn($x)=>url('leads',array_filter(['q'=>$q,'status'=>$st,'src'=>$src,'tag'=>$tag,'own'=>$own,'fu'=>$fu,'view'=>$view]+$x,'strlen'));
?>
<div class="kpis"><div class="kpi"><span class="hi hi-g"><?=icon('users')?></span><div><span>Total leads</span><b><?=(int)$k['t']?></b><small><?=(int)$k['td']?> added today</small></div></div><div class="kpi"><span class="hi hi-b"><?=icon('zap')?></span><div><span>New / uncontacted</span><b><?=(int)$k['nw']?></b><small>need a first touch</small></div></div><div class="kpi"><span class="hi hi-o"><?=icon('clock')?></span><div><span>Follow-ups due</span><b><?=(int)$k['due']?></b><small><a class="lnk" href="<?=$qs(['fu'=>'due'])?>">View due</a></small></div></div><div class="kpi kpi-n"><span class="hi hi-y"><?=icon('target')?></span><div><span>Won</span><b><?=(int)$k['wn']?></b><small><?=money($k['wv'])?> deal value</small></div></div></div>
<div class="ph"><div class="seg"><a href="<?=$qs(['src'=>''])?>" class="<?=$src===''?'on':''?>">All <em class="muted"><?=array_sum($sc)?></em></a><?php foreach(lead_sources() as $kk=>[$lb,$c,$ic]):if(empty($sc[$kk])&&$src!==$kk)continue;?><a href="<?=$qs(['src'=>$kk])?>" class="<?=$src===$kk?'on':''?>"><?=icon($ic)?><?=e($lb)?> <em class="muted"><?=$sc[$kk]??0?></em></a><?php endforeach?></div><div class="pha"><div class="seg"><a href="<?=$qs(['view'=>'list'])?>" class="<?=$view==='list'?'on':''?>"><?=icon('list')?>List</a><a href="<?=$qs(['view'=>'board'])?>" class="<?=$view==='board'?'on':''?>"><?=icon('kanban')?>Board</a></div><button class="btn" onclick="A.modal('m-imp')"><?=icon('upload')?>Import</button><a class="btn" href="<?=$qs(['export'=>1])?>"><?=icon('download')?>Export</a><button class="btn btn-y" onclick="A.modal('m-add')"><?=icon('plus')?>Add lead</button></div></div>
<form class="fl card" method="get"><input type="hidden" name="r" value="leads"><input type="hidden" name="view" value="<?=$view?>"><input type="hidden" name="src" value="<?=e($src)?>"><label class="f2"><?=icon('search')?><input name="q" value="<?=e($q)?>" placeholder="Search name, phone, email, city, tag or any field…"></label><?php if($view==='list'):?><select name="status"><option value="">Any status</option><?php foreach(crm_statuses() as $kk=>[$lb]):?><option value="<?=$kk?>" <?=$st===$kk?'selected':''?>><?=e($lb)?></option><?php endforeach?></select><?php endif?><select name="own"><option value="">Anyone</option><option value="me" <?=$own==='me'?'selected':''?>>Assigned to me</option><option value="none" <?=$own==='none'?'selected':''?>>Unassigned</option></select><select name="fu"><option value="">Any follow-up</option><option value="due" <?=$fu==='due'?'selected':''?>>Follow-up due</option></select><input name="tag" value="<?=e($tag)?>" placeholder="Tag" style="max-width:130px"><button class="btn btn-n"><?=icon('filter')?>Filter</button></form>
<?php if($view==='board'):$cols=[];foreach($leads as $l)$cols[$l['status']][]=$l;?>
<div class="kb"><?php foreach(crm_statuses() as $kk=>[$lb,$c]):$list=$cols[$kk]??[];?><div class="kc" data-status="<?=$kk?>"><div class="kc-h"><span><i class="bdg-<?=$c?>" style="background:currentColor"></i><?=e($lb)?></span><em><?=count($list)?></em></div><?php foreach($list as $l):?><div class="kcard" data-id="<?=$l['id']?>"><a href="<?=url('lead',['id'=>$l['id']])?>"><b><?=e($l['contact_name']?:$l['name'])?></b></a><small><?=e($l['contact_name']&&$l['name']!==$l['contact_name']?$l['name']:($l['phone']?:$l['email']))?></small><div class="km"><?=srcbadge($l['source'])?><?php if($l['deal_value']):?><b class="sm"><?=money($l['deal_value'])?></b><?php endif?></div><?php if($l['follow_up_at']):?><small class="<?=strtotime($l['follow_up_at'])<=time()?'red':''?>" style="margin-top:4px"><?=icon('clock')?> <?=date('d M, h:i A',strtotime($l['follow_up_at']))?></small><?php endif?></div><?php endforeach?></div><?php endforeach?></div>
<?php else:?>
<div class="card p0"><form id="bulk" method="post" class="bulk"><?=csrf_field()?><input type="hidden" name="a" id="bulk-a"><span class="bsel"><b id="selc">0</b> selected</span><div class="dd"><button type="button" class="btn btn-sm" onclick="this.parentNode.classList.toggle('open')"><?=icon('target')?>Set status ▾</button><div class="ddm"><?php foreach(crm_statuses() as $kk=>[$lb]):?><button type="button" onclick="A.bulk('status:<?=$kk?>')"><?=e($lb)?></button><?php endforeach?></div></div><?php if($autos):?><div class="dd"><button type="button" class="btn btn-sm" onclick="this.parentNode.classList.toggle('open')"><?=icon('bot')?>Add to automation ▾</button><div class="ddm"><?php foreach($autos as $au):?><button type="button" onclick="A.bulk('auto:<?=$au['id']?>','Start this automation for the selected leads?')"><?=e($au['name'])?></button><?php endforeach?></div></div><?php endif?><button type="button" class="btn btn-sm" onclick="A.bulk('initiate','Run the website & Google audit + PDF report for the selected leads?')"><?=icon('file')?>Audit &amp; report</button><button type="button" class="btn btn-sm btn-r" onclick="A.bulk('delete','Delete the selected leads and all their history?')"><?=icon('trash')?></button></form>
<?php if(!$leads):?><div class="empty"><?=icon('users','eic')?><h4>No leads yet</h4><p>Add a lead, import a CSV, connect a website form or ads in <a class="lnk" href="<?=url('settings',['tab'=>'capture'])?>">Settings → Lead capture</a>, or move won businesses from Scraped Data.</p><button class="btn btn-y" onclick="A.modal('m-add')"><?=icon('plus')?>Add lead</button></div><?php else:?>
<div class="tw"><table class="tbl"><thead><tr><th class="cb"><input type="checkbox" data-all></th><th>Lead</th><th>Contact</th><th>Source</th><th>Status</th><th>Deal</th><th>Follow-up</th><th>Owner</th><th>Last activity</th><th></th></tr></thead><tbody><?php foreach($leads as $l):?><tr><td class="cb"><input type="checkbox" name="ids[]" value="<?=$l['id']?>" form="bulk"></td><td class="biz"><a href="<?=url('lead',['id'=>$l['id']])?>"><b><?=e($l['contact_name']?:$l['name'])?></b></a><small><?=e(implode(' · ',array_filter([$l['contact_name']&&$l['name']!==$l['contact_name']?$l['name']:$l['city'],$l['service']])))?></small><?php foreach(array_filter(array_map('trim',explode(',',(string)$l['tags']))) as $t):?><span class="bdg bdg-gray sm"><?=e($t)?></span> <?php endforeach?></td><td class="ctc"><?php if($l['phone']):?><span><?=icon('phone')?><?=e($l['phone'])?></span><?php endif?><?php if($l['email']):?><span><?=icon('mail')?><?=e(mb_strimwidth($l['email'],0,30,'…'))?></span><?php endif?></td><td><?=srcbadge($l['source'])?><?php if($l['source_detail']):?><small class="muted" style="display:block;max-width:180px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis"><?=e($l['source_detail'])?></small><?php endif?></td><td><?=sbadge($l['status'])?></td><td class="nowrap"><?=$l['deal_value']?money($l['deal_value']):'<span class="muted">—</span>'?></td><td class="nowrap sm <?=$l['follow_up_at']&&strtotime($l['follow_up_at'])<=time()&&!in_array($l['status'],['won','lost'],true)?'red':''?>"><?=$l['follow_up_at']?date('d M, h:i A',strtotime($l['follow_up_at'])):'—'?></td><td class="sm"><?=e($l['owner']??'—')?></td><td class="muted nowrap sm"><?=ago($l['last_activity']?:$l['created_at'])?></td><td class="act"><?php if($l['phone']):?><a class="ib" href="tel:<?=e(preg_replace('/[^\d+]/','',$l['phone']))?>" title="Call"><?=icon('phone')?></a><a class="ib" href="<?=e(WhatsApp::link($l['phone'],''))?>" target="_blank" rel="noopener" title="WhatsApp"><?=icon('wa')?></a><?php endif?><a class="ib" href="<?=url('lead',['id'=>$l['id']])?>" title="Open"><?=icon('eye')?></a></td></tr><?php endforeach?></tbody></table></div><?php if($pages>1):?><div class="pg"><span class="muted"><?=$total?> leads</span><?php for($i=max(1,$pg-3);$i<=min($pages,$pg+3);$i++):?><a href="<?=$qs(['p'=>$i])?>" class="<?=$i===$pg?'on':''?>"><?=$i?></a><?php endfor?></div><?php endif?><?php endif?></div>
<?php endif?>
<div class="md" id="m-add"><form class="md-b lg" method="post"><?=csrf_field()?><input type="hidden" name="a" value="add"><div class="md-h"><h3><span class="hi hi-g"><?=icon('user')?></span>Add lead</h3><button type="button" class="ib" onclick="A.close()"><?=icon('x')?></button></div><div class="fg"><label>Contact person<input name="contact_name" placeholder="Full name"></label><label>Business / company<input name="name"></label><label>Phone / WhatsApp<input name="phone" type="tel"></label><label>Email<input name="email" type="email"></label><label>City<input name="city"></label><label>Website<input name="website" placeholder="example.com"></label><label>Service interested in<input name="service"></label><label>Deal value (<?=e(setting('currency_symbol','₹'))?>)<input name="deal_value" type="number" step="0.01"></label><label>Status<select name="status"><?php foreach(crm_statuses() as $kk=>[$lb]):?><option value="<?=$kk?>"><?=e($lb)?></option><?php endforeach?></select></label><label>Follow-up<input name="follow_up_at" type="datetime-local"></label><label>Tags<input name="tags" placeholder="hot, referral"></label><label>Address<input name="address"></label><?php foreach(CRM::fields() as $f):?><label class="<?=$f['type']==='textarea'?'full':''?>"><?=e($f['label'])?><?=CRM::input($f)?></label><?php endforeach?><label class="full">Notes / message<textarea name="message" rows="3"></textarea></label></div><p class="hint">Need other fields? Add them in <a class="lnk" href="<?=url('settings',['tab'=>'fields'])?>">Settings → Custom fields</a>.</p><div class="md-f"><button type="button" class="btn" onclick="A.close()">Cancel</button><button class="btn btn-y"><?=icon('check')?>Save lead</button></div></form></div>
<div class="md" id="m-imp"><form class="md-b" method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="a" value="import"><div class="md-h"><h3><span class="hi hi-b"><?=icon('upload')?></span>Import leads from CSV</h3><button type="button" class="ib" onclick="A.close()"><?=icon('x')?></button></div><p class="muted">First row must be column names. We recognise common names automatically: <code>name</code>, <code>company</code>, <code>phone</code>, <code>mobile</code>, <code>email</code>, <code>city</code>, <code>website</code>, <code>service</code>, <code>budget</code>, <code>message</code>, plus your custom field keys. Other columns are saved in notes. Duplicates (same phone/email in 30 days) are merged.</p><label>CSV file<input type="file" name="csv" accept=".csv,text/csv" required></label><div class="md-f"><button type="button" class="btn" onclick="A.close()">Cancel</button><button class="btn btn-y"><?=icon('upload')?>Import</button></div></form></div>
<?php if(isset($_GET['add'])):?><script>addEventListener('load',function(){A.modal('m-add')})</script><?php endif?>
